  `tp` decimal(7,2) NOT NULL DEFAULT '0.00' COMMENT 'Curah hujan prakiraan (mm, field: tp)',
  `weather` tinyint unsigned DEFAULT NULL COMMENT 'Kode kondisi cuaca BMKG (field: weather)',
  `weather_desc` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Deskripsi cuaca (Indonesia, field: weather_desc)',
  `weather_desc_en` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Deskripsi cuaca (Inggris, field: weather_desc_en)',
  `t` tinyint DEFAULT NULL COMMENT 'Suhu udara (°C, field: t)',
  `tcc` tinyint unsigned DEFAULT NULL COMMENT 'Total cloud cover / tutupan awan (%, field: tcc)',
  `hu` tinyint unsigned DEFAULT NULL COMMENT 'Kelembaban udara / humidity (%, field: hu)',
  `wd_deg` smallint unsigned DEFAULT NULL COMMENT 'Arah angin datang (derajat, field: wd_deg)',
  `wd` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Arah angin datang (singkatan, field: wd)',
  `wd_to` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Arah angin menuju (singkatan, field: wd_to)',
  `ws` decimal(5,2) DEFAULT NULL COMMENT 'Kecepatan angin (m/s, field: ws)',
  `vs` int unsigned DEFAULT NULL COMMENT 'Jarak pandang / visibility (meter, field: vs)',
  `vs_text` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Jarak pandang teks (field: vs_text)',
  `analysis_date` datetime DEFAULT NULL COMMENT 'Tanggal rilis analisis BMKG (field: analysis_date)',
  `time_index` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Indeks slot waktu BMKG (field: time_index)',
  `image_url` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL ikon cuaca (field: image)',
