--
-- Table structure for table `bmkg_summary_harian`
--

DROP TABLE IF EXISTS `bmkg_summary_harian`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bmkg_summary_harian` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `lokasi_id` int unsigned NOT NULL COMMENT 'FK ke bmkg_lokasi',
  `tanggal` date NOT NULL COMMENT 'Tanggal lokal ringkasan',
  `total_tp_mm` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT 'Total curah hujan 24 jam (SUM tp dari bmkg_prakiraan)',
  `max_tp_mm` decimal(7,2) NOT NULL DEFAULT '0.00' COMMENT 'Curah hujan tertinggi dalam satu periode 3 jam',
  `jumlah_periode` tinyint unsigned DEFAULT '0' COMMENT 'Jumlah periode prakiraan yang teragregasi (maks 8 per hari)',
  `synced_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_lokasi_tanggal` (`lokasi_id`,`tanggal`),
  KEY `idx_lokasi_id` (`lokasi_id`),
  KEY `idx_tanggal` (`tanggal`),
  KEY `idx_total_tp` (`total_tp_mm`),
  CONSTRAINT `fk_summary_lokasi` FOREIGN KEY (`lokasi_id`) REFERENCES `bmkg_lokasi` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Ringkasan curah hujan harian (derived dari bmkg_prakiraan) — dipakai agent Step 3 rainfall branching';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `bmkg_summary_harian`
--

