--
-- Table structure for table `onlimo_stasiun`
--

DROP TABLE IF EXISTS `onlimo_stasiun`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `onlimo_stasiun` (
  `station_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ID stasiun dari API (contoh: KLHK1, KLHK02)',
  `station_name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nama stasiun pemantauan',
  `nama_sungai` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nama sungai / danau',
  `nama_das` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nama Daerah Aliran Sungai',
  `provinsi` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kabkot` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Kabupaten / Kota',
  `kecamatan` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `latitude` decimal(10,7) NOT NULL,
  `longitude` decimal(10,7) NOT NULL,
  `status_aktif` tinyint(1) NOT NULL DEFAULT '1',
  `synced_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Waktu terakhir data di-sync dari API',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`station_id`),
  KEY `idx_das` (`nama_das`),
  KEY `idx_kabkot` (`kabkot`),
  KEY `idx_koordinat` (`latitude`,`longitude`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Master data stasiun Onlimo KLHK';
/*!40101 SET character_set_client = @saved_cs_client */;

