--
-- Table structure for table `onlimo_status`
--

DROP TABLE IF EXISTS `onlimo_status`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `onlimo_status` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `station_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'FK ke onlimo_stasiun (IDStasiun)',
  `tanggal_validasi` date NOT NULL COMMENT 'Tanggal status divalidasi oleh Onlimo',
  `tanggal_data` date NOT NULL COMMENT 'Tanggal data sensor yang jadi dasar status',
  `indeks` decimal(5,2) DEFAULT NULL COMMENT 'Indeks Mutu Air tervalidasi (field: indeks)',
  `status_nama` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Label status: BAIK / CEMAR RINGAN / CEMAR SEDANG / CEMAR BERAT (field: status_nama)',
  `status_warna` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Hex color code untuk UI (field: status_warna, contoh: 4F81BC)',
  `parameter_kritis` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Parameter penentu status terburuk (field: kritis, contoh: BOD)',
  `max_parameter` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Parameter dengan nilai tertinggi (field: max_parameter)',
  `max_nilai` decimal(12,3) DEFAULT NULL COMMENT 'Nilai tertinggi dari max_parameter (field: max_nilai)',
  `keterangan` text COLLATE utf8mb4_unicode_ci COMMENT 'Catatan tambahan dari Onlimo (field: keterangan)',
  `synced_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_station_tgl_validasi` (`station_id`,`tanggal_validasi`),
  KEY `idx_station_id` (`station_id`),
  KEY `idx_tanggal_validasi` (`tanggal_validasi`),
  KEY `idx_indeks` (`indeks`),
  KEY `idx_status_nama` (`status_nama`),
  KEY `idx_parameter_kritis` (`parameter_kritis`),
  CONSTRAINT `fk_status_stasiun` FOREIGN KEY (`station_id`) REFERENCES `onlimo_stasiun` (`station_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=524 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Status indeks mutu air harian tervalidasi per stasiun Onlimo KLHK';
/*!40101 SET character_set_client = @saved_cs_client */;

