--
-- Table structure for table `sitala_ika`
--

DROP TABLE IF EXISTS `sitala_ika`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sitala_ika` (
  `uid_indeks_history` int unsigned NOT NULL COMMENT 'ID unik dari API SITALA (field: uid_indeks_history)',
  `uid_provinsi` smallint unsigned NOT NULL COMMENT 'ID provinsi di SITALA (field: uid_provinsi)',
  `uid_kabkota` smallint unsigned NOT NULL COMMENT 'ID kabupaten/kota di SITALA (field: uid_kabkota)',
  `tahun` year NOT NULL COMMENT 'Tahun data indeks (field: tahun)',
  `nama_provinsi` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nama provinsi (field: nama_provinsi)',
  `nama_kabkota` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nama kabupaten/kota (field: nama_kabkota)',
  `kd_regional` tinyint unsigned DEFAULT NULL COMMENT 'Kode regional (field: kd_regional)',
  `ika` decimal(6,2) DEFAULT NULL,
  `iku` decimal(6,2) DEFAULT NULL,
  `ikl` decimal(6,2) DEFAULT NULL,
  `ikal` decimal(6,2) DEFAULT NULL,
  `ikeg` decimal(6,2) DEFAULT NULL,
  `iklh` decimal(6,2) DEFAULT NULL,
  `jenis_indeks` tinyint unsigned DEFAULT '0' COMMENT 'Tipe perhitungan indeks (field: jenis_indeks)',
  `target_iklh` decimal(6,2) DEFAULT NULL,
  `target_ika` decimal(6,2) DEFAULT NULL,
  `target_iku` decimal(6,2) DEFAULT NULL,
  `target_ikl` decimal(6,2) DEFAULT NULL,
  `target_ikal` decimal(6,2) DEFAULT NULL,
  `ir_lb` decimal(6,2) DEFAULT NULL COMMENT 'IR Lahan Baik (field: ir_lb)',
  `ir_kb` decimal(6,2) DEFAULT NULL COMMENT 'IR Kerusakan Badan Air (field: ir_kb)',
  `ir_ih` decimal(6,2) DEFAULT NULL COMMENT 'IR Irigasi/Hidrologi (field: ir_ih)',
  `ir_pl` decimal(6,2) DEFAULT NULL COMMENT 'IR Pencemaran Laut (field: ir_pl)',
  `ir_gl` decimal(6,2) DEFAULT NULL COMMENT 'IR Gambut/Lahan (field: ir_gl)',
  `ir_lh` decimal(6,2) DEFAULT NULL COMMENT 'IR Total Lingkungan Hidup (field: ir_lh)',
  `rekomendasi_ika` text COLLATE utf8mb4_unicode_ci COMMENT 'Rekomendasi untuk IKA (field: rekomendasi_ika)',
  `rekomendasi_iku` text COLLATE utf8mb4_unicode_ci COMMENT 'Rekomendasi untuk IKU (field: rekomendasi_iku)',
  `rekomendasi_ikl` text COLLATE utf8mb4_unicode_ci COMMENT 'Rekomendasi untuk IKL (field: rekomendasi_ikl)',
  `rekomendasi_ikal` text COLLATE utf8mb4_unicode_ci COMMENT 'Rekomendasi untuk IKAL (field: rekomendasi_ikal)',
  `rekomendasi_iklh` text COLLATE utf8mb4_unicode_ci COMMENT 'Rekomendasi untuk IKLH (field: rekomendasi_iklh)',
  `peta_iku` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nama file peta IKU (field: peta_sebaran_iku)',
  `peta_ika` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nama file peta IKA (field: peta_sebaran_ika)',
  `peta_ikl` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nama file peta IKL (field: peta_sebaran_ikl)',
  `gambut_provinsi` tinyint(1) DEFAULT NULL COMMENT 'Flag wilayah gambut tingkat provinsi',
  `gambut_kabkota` tinyint(1) DEFAULT NULL COMMENT 'Flag wilayah gambut tingkat kabkota',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Soft-delete flag dari API',
  `hidden` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Hidden flag dari API',
  `crdate` datetime DEFAULT NULL COMMENT 'Tanggal dibuat di SITALA (konversi Unix ts dari field: crdate)',
  `chdate` datetime DEFAULT NULL COMMENT 'Tanggal diubah di SITALA (konversi Unix ts dari field: chdate)',
  `trend_yoy` decimal(6,2) DEFAULT NULL COMMENT 'Selisih IKA vs tahun lalu (dihitung ETL)',
  `synced_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`uid_indeks_history`),
  UNIQUE KEY `uq_kabkota_tahun` (`uid_kabkota`,`tahun`),
  KEY `idx_uid_kabkota` (`uid_kabkota`),
  KEY `idx_uid_provinsi` (`uid_provinsi`),
  KEY `idx_nama_kabkota` (`nama_kabkota`),
  KEY `idx_tahun` (`tahun`),
  KEY `idx_ika` (`ika`),
  KEY `idx_deleted_hidden` (`deleted`,`hidden`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Indeks Kualitas Lingkungan Hidup (IKLH/IKA/IKU/IKL) per kabupaten-kota dari API SITALA KLHK';
/*!40101 SET character_set_client = @saved_cs_client */;

