--
-- Table structure for table `sparing_industri`
--

DROP TABLE IF EXISTS `sparing_industri`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sparing_industri` (
  `id` int unsigned NOT NULL COMMENT 'ID industri dari API (field: industri.id)',
  `name` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nama perusahaan (field: industri.name)',
  `type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Jenis industri (field: industri.type, contoh: KERTAS DAN PULP)',
  `address` text COLLATE utf8mb4_unicode_ci COMMENT 'Alamat lengkap (field: industri.address)',
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'No. telepon (field: industri.phone)',
  `email` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Email (field: industri.email)',
  `id_simpel` int unsigned DEFAULT NULL COMMENT 'ID di sistem SIMPEL KLHK (field: industri.id_simpel)',
  `id_ppa` bigint unsigned DEFAULT NULL COMMENT 'ID di sistem PPA KLHK (field: industri.id_ppa)',
  `synced_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_type` (`type`),
  KEY `idx_id_simpel` (`id_simpel`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Master data perusahaan/industri yang terdaftar di Sparing KLHK';
/*!40101 SET character_set_client = @saved_cs_client */;

