-- Table structure for table `sparing_logger`
--

DROP TABLE IF EXISTS `sparing_logger`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sparing_logger` (
  `id` int unsigned NOT NULL COMMENT 'ID integer logger dari API (field: id)',
  `id_logger` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'MongoDB ObjectID logger (field: id_logger) — dipakai di monitoring API',
  `id_industries` int unsigned NOT NULL COMMENT 'FK ke sparing_industri (field: id_industries)',
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nama outlet/logger (field: name)',
  `brand` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Merek perangkat logger (field: brand)',
