  `logger_existing` tinyint(1) DEFAULT '1' COMMENT 'Flag logger masih terpasang (field: logger_existing)',
  `synced_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_id_logger` (`id_logger`),
  KEY `idx_id_industries` (`id_industries`),
  KEY `idx_status` (`status`),
  KEY `idx_koordinat` (`latitude`,`longitude`),
  CONSTRAINT `fk_logger_industri` FOREIGN KEY (`id_industries`) REFERENCES `sparing_industri` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Logger/outlet IPAL per perusahaan Sparing — satu industri bisa punya banyak logger';
