--
-- Table structure for table `sparing_monitoring`
--

DROP TABLE IF EXISTS `sparing_monitoring`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sparing_monitoring` (
  `id` int unsigned NOT NULL COMMENT 'ID record monitoring dari API (field: id)',
  `id_logger` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'MongoDB ObjectID logger (field: id_logger)',
  `id_logger_int` int unsigned DEFAULT NULL COMMENT 'ID integer logger (field: id_logger_)',
  `id_parameter` tinyint unsigned NOT NULL COMMENT 'ID tipe parameter (field: id_parameter)',
  `reported_at` date NOT NULL COMMENT 'Tanggal laporan (field: reported_at)',
  `counter` int unsigned DEFAULT NULL,
  `total` double DEFAULT NULL,
  `average` double DEFAULT NULL,
  `value` double DEFAULT NULL,
  `unit` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `min_valid` tinyint unsigned DEFAULT NULL COMMENT 'Minimum pembacaan valid yang dibutuhkan (field: min_valid)',
  `bm` double DEFAULT NULL,
  `bm_max` double DEFAULT NULL,
  `bm_min_use` double DEFAULT NULL,
  `bm_max_use` double DEFAULT NULL,
  `parameter_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status_taat` enum('TAAT','LANGGAR','TIDAK_VALID') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Kepatuhan baku mutu — dihitung ETL; TIDAK_VALID jika counter < min_valid',
  `updated_at` datetime DEFAULT NULL COMMENT 'Waktu update di Sparing (field: updated_at)',
  `synced_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_logger_param_tgl` (`id_logger`,`id_parameter`,`reported_at`),
  KEY `idx_id_logger` (`id_logger`),
  KEY `idx_id_logger_int` (`id_logger_int`),
  KEY `idx_reported_at` (`reported_at`),
  KEY `idx_parameter_name` (`parameter_name`),
  KEY `idx_status_taat` (`status_taat`),
  CONSTRAINT `fk_monitoring_logger` FOREIGN KEY (`id_logger`) REFERENCES `sparing_logger` (`id_logger`) ON DELETE CASCADE ON UPDATE CASCADE
