--
-- Table structure for table `sparing_parameter_logger`
--

DROP TABLE IF EXISTS `sparing_parameter_logger`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sparing_parameter_logger` (
  `id` int unsigned NOT NULL COMMENT 'ID registrasi sensor dari API (field: parameters[].id)',
  `id_logger` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'FK ke sparing_logger.id_logger (field: id_logger)',
  `id_logger_int` int unsigned DEFAULT NULL COMMENT 'FK integer ke sparing_logger.id',
  `id_parameter` tinyint unsigned NOT NULL COMMENT 'ID tipe parameter (1=pH, 2=COD, 3=TSS, 5=debit, field: id_parameter)',
  `brand` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Merek sensor (field: parameters[].brand)',
  `type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `schedule` tinyint unsigned DEFAULT NULL COMMENT 'Jadwal pelaporan (jam, field: schedule)',
  `range_sensor` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Rentang ukur sensor (field: range_sensor)',
  `brosur_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL brosur sensor (field: brosur_url)',
  `bm` decimal(15,4) DEFAULT NULL COMMENT 'Baku mutu maksimum (field: bm)',
  `bm_max` decimal(15,4) DEFAULT NULL COMMENT 'Batas atas baku mutu (untuk pH, field: bm_max)',
  `parameter_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `parameter_unit` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `synced_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_logger_parameter` (`id_logger`,`id_parameter`),
  KEY `idx_id_logger` (`id_logger`),
  KEY `idx_id_parameter` (`id_parameter`),
  KEY `idx_parameter_name` (`parameter_name`),
  CONSTRAINT `fk_param_logger` FOREIGN KEY (`id_logger`) REFERENCES `sparing_logger` (`id_logger`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Registrasi sensor dan baku mutu per parameter per logger Sparing';
/*!40101 SET character_set_client = @saved_cs_client */;

